	<script>
		// Функция для дублирования элемента
		function duplicateElement() {
			// Находим оригинальный элемент
			var original = document.getElementById('origin-p');
			// Клонируем элемент
			var clone = original.cloneNode(true);
			// Удаляем id у клонированного элемента
			clone.removeAttribute('id');
			// Изменяем id внутреннего элемента
			var innerElement = clone.querySelector('#order_product_<?php echo $arResult['ID']; ?>');
			if (innerElement) {
				innerElement.id = 'order_product_dub';
			}
			// Находим целевой div
			var targetDiv = document.getElementById('dubal-p');
			// Добавляем клонированный элемент в целевой div
			targetDiv.appendChild(clone);
		}

		// Дублируем элемент при загрузке страницы
		window.onload = duplicateElement;

	</script>








