<script>


	window.addEventListener('load', function () {
		document.getElementById('order_product_dub').addEventListener('click', function () {
			document.getElementById('order_product_<?php echo $arResult['ID']; ?>').click();
		});
	});






	function openTabProduct(evt, productName) {
		var i, tabcontent, tablinks;
		tabcontent = document.getElementsByClassName("tabcontent");
		for (i = 0; i < tabcontent.length; i++) {
			tabcontent[i].style.display = "none";
		}
		tablinks = document.getElementsByClassName("tablinks");
		for (i = 0; i < tablinks.length; i++) {
			tablinks[i].className = tablinks[i].className.replace(" active", "");
		}
		document.getElementById(productName).style.display = "flex";
		evt.currentTarget.className += " active";
	}
	document.getElementById('one_tab').click();




</script>